<script setup lang="ts">
import { defineAsyncComponent, computed, onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { useRoute, useRouter, onBeforeRouteLeave } from 'vue-router';
import { api, ApiError, errorText, mutationId, session } from '../api';
import { useRouteDraft } from '../useRouteDraft';
import { clone, validPosition, modeLabels, travelModes, geometryLimits, geometrySourceLabels, type RoutingCandidate, type GeometryAsset, type GeometrySummary, type GeometrySaveInput, type GpxPreview, type ExportReport, type RouteSnapshot, type JourneySummary, type Location, type RouteGeometry } from '../../../packages/contracts/src/index.js';
import RouteMapCanvas from '../components/RouteMapCanvas.vue';
import RoutingPanel from '../components/RoutingPanel.vue';
const OutdoorMapCanvas = defineAsyncComponent(() => import('../components/OutdoorMapCanvas.vue'));
import AtlasIcon from '../components/AtlasIcon.vue';
import ModalSheet from '../components/ModalSheet.vue';
import '../styles/maps.css';
const page = useRoute(), router = useRouter(), draft = useRouteDraft(); const { route, base, dirty, saving, error, conflict, savedMessage } = draft;
const actual = page.path.includes('/actual/map'), journey = ref<JourneySummary | null>(null), loading = ref(true), loadError = ref(''), message = ref('');
const segmentId = ref(''), stopId = ref(''), assets = ref<GeometrySummary[]>([]), asset = ref<GeometryAsset | null>(null), assetLoading = ref(false), busy = ref(false), storageOK = ref(true), drawingConflict = ref(false);
const mapMode = ref<'amap' | 'outdoor'>('amap'), routingPreview = ref<RoutingCandidate | null>(null), routingBusy = ref(false);
watch(mapMode, value => { action.value = 'none'; if (!drawing.value) manualCrs.value = value === 'outdoor' ? 'WGS84' : 'GCJ02'; else if (drawing.value.kind === 'manual' && drawing.value.geometry.crs === (value === 'outdoor' ? 'WGS84' : 'GCJ02')) action.value = 'draw'; });
const action = ref<'none' | 'point' | 'draw'>('none'), manualCrs = ref<'GCJ02' | 'WGS84'>('GCJ02'), mode = ref('hike'), preview = ref<GpxPreview | null>(null);
type Drawing = { kind: 'manual' | 'gpx'; geometry: RouteGeometry; xml: string; filename: string; sourceNote: string; rightsConfirmed: boolean; segmentId: string; baseVersion: number; expectedGeometryRef: string | null; key: string };
const drawing = ref<Drawing | null>(null), pointInput = reactive({ longitude: '', latitude: '' }), locationInput = reactive({ longitude: '', latitude: '', crs: 'WGS84' as Location['crs'] });
const fileInput = ref<HTMLInputElement>(); const segment = computed(() => route.value?.segments.find(s => s.id === segmentId.value)), stops = computed(() => route.value?.days.flatMap(d => d.stops) ?? []), stop = computed(() => stops.value.find(p => p.id === stopId.value));
const editable = computed(() => !saving.value && !busy.value && !routingBusy.value && !conflict.value && !drawingConflict.value), geometry = computed(() => drawing.value?.geometry ?? routingPreview.value?.geometry ?? asset.value?.geometry ?? null);
const names = (id: string) => stops.value.find(p => p.id === id)?.label ?? '地点已移除';
const pointCount = computed(() => drawing.value?.geometry.parts.reduce((n, part) => n + part.length, 0) ?? 0);
const modal = ref<'leave' | 'export' | 'reload' | null>(null), report = ref<ExportReport | null>(null), partialOK = ref(false); let resolveLeave: ((answer: boolean) => void) | undefined, storageKey = '', assetGeneration = 0, restoring = false;
const signature = computed(() => drawing.value ? JSON.stringify({ ...drawing.value, key: undefined }) : '');
function persistDrawing() { if (!storageKey) return; try { if (drawing.value) localStorage.setItem(storageKey, JSON.stringify(drawing.value)); else localStorage.removeItem(storageKey); storageOK.value = true; } catch { storageOK.value = false; } }
watch(signature, () => { if (drawing.value && !busy.value && !restoring) drawing.value.key = mutationId(); if (!restoring) persistDrawing(); }, { flush: 'sync' });
async function loadAssets() { if (route.value) assets.value = await api('/routes/' + route.value.id + '/geometries'); }
async function loadAsset() {
  const generation = ++assetGeneration; asset.value = null; const id = segment.value?.geometryRef; if (!id) return; assetLoading.value = true;
  try { const result = await api<GeometryAsset>('/geometries/' + id); if (generation === assetGeneration) asset.value = result; }
  catch (e) { if (generation === assetGeneration) error.value = errorText(e); } finally { if (generation === assetGeneration) assetLoading.value = false; }
}
watch(segmentId, () => { routingPreview.value = null; action.value = 'none'; mode.value = segment.value?.mode === 'unknown' ? 'hike' : segment.value?.mode ?? 'hike'; void loadAsset(); });
watch(stop, value => { locationInput.longitude = value?.location ? String(value.location.longitude) : ''; locationInput.latitude = value?.location ? String(value.location.latitude) : ''; locationInput.crs = value?.location?.crs ?? 'WGS84'; }, { immediate: true });
async function load() {
  loading.value = true; loadError.value = '';
  try {
    journey.value = await api('/journeys/' + page.params.id); const routeId = actual ? journey.value!.actualRouteId : journey.value!.planRouteId;
    if (!routeId) throw new Error('还没有实际记录，请先回到行程创建。');
    draft.initialize(await api<RouteSnapshot>('/routes/' + routeId)); segmentId.value = route.value!.segments[0]?.id ?? ''; stopId.value = stops.value[0]?.id ?? ''; await loadAssets();
    let tab = 'fallback'; try { tab = sessionStorage.getItem('tj:tab') || mutationId(); sessionStorage.setItem('tj:tab', tab); } catch { storageOK.value = false; }
    storageKey = `tj:map:${session.value!.user.id}:${routeId}:${tab}`;
    try { const text = localStorage.getItem(storageKey); if (text) { const saved = JSON.parse(text) as Drawing; if (!['manual', 'gpx'].includes(saved.kind) || !saved.geometry?.parts || typeof saved.key !== 'string' || !route.value!.segments.some(s => s.id === saved.segmentId)) throw new Error(); restoring = true; drawing.value = saved; restoring = false; segmentId.value = saved.segmentId; drawingConflict.value = saved.baseVersion !== base.value!.version || saved.expectedGeometryRef !== segment.value?.geometryRef; message.value = '已恢复此页面的路径草稿'; if (saved.kind === 'gpx') await previewGpx(); } }
    catch { error.value = '路径草稿暂时无法完整恢复，原草稿未主动删除；请核对或下载当前内容。'; }
    await loadAsset();
  } catch (e) { loadError.value = errorText(e); } finally { loading.value = false; }
}
onMounted(load);
function updateLocation(location: Location | null) { if (!editable.value || !stop.value || drawing.value) return; if (draft.stage([{ type: 'update_stop', stopId: stop.value.id, patch: { location } }])) { action.value = 'none'; message.value = '位置已加入行程修改，请保存；相关旧路径会标记过期。'; } }
function enterLocation() { const longitude = Number(locationInput.longitude), latitude = Number(locationInput.latitude); if (!locationInput.longitude.trim() || !locationInput.latitude.trim() || !validPosition([longitude, latitude])) { error.value = '请填写有效的经纬度，并选择原始坐标系。'; return; } updateLocation({ longitude, latitude, crs: locationInput.crs, source: 'manual_coordinate' }); }
function mapPick(location: Location) { if (!editable.value) return; if (action.value === 'point') updateLocation(location); else if (action.value === 'draw' && drawing.value?.kind === 'manual' && drawing.value.geometry.crs === location.crs) addPoint(location.longitude, location.latitude); }
function setMode() { if (!segment.value || !editable.value || drawing.value) return; draft.stage([{ type: 'set_arrival', stopId: segment.value.toStopId, mode: mode.value as typeof travelModes[number] }]); }
function start(kind: 'manual' | 'gpx') {
  if (!segment.value || !editable.value || dirty.value || drawing.value || segment.value.geometryLocked || segment.value.kind === 'gap') return;
  preview.value = null; error.value = ''; drawing.value = { kind, geometry: { crs: manualCrs.value, parts: [[]] }, xml: '', filename: '', sourceNote: kind === 'manual' ? manualCrs.value === 'GCJ02' ? '本人在高德底图上手工补绘（GCJ-02）' : mapMode.value === 'outdoor' ? '本人在 OpenHikingMap 上补绘；© OpenHikingMap；© OpenStreetMap contributors, ODbL 1.0 https://www.openstreetmap.org/copyright' : '本人根据自有 WGS84 坐标手工补绘' : '', rightsConfirmed: false, segmentId: segment.value.id, baseVersion: base.value!.version, expectedGeometryRef: segment.value.geometryRef, key: mutationId() };
  action.value = kind === 'manual' && manualCrs.value === (mapMode.value === 'outdoor' ? 'WGS84' : 'GCJ02') ? 'draw' : 'none';
}
function addPoint(longitude = Number(pointInput.longitude), latitude = Number(pointInput.latitude)) {
  if (!drawing.value || drawing.value.kind !== 'manual' || !editable.value) return;
  if (!validPosition([longitude, latitude]) || pointCount.value >= geometryLimits.points) { error.value = '请检查经纬度，单条几何最多 10000 个点。'; return; }
  drawing.value.geometry.parts.at(-1)!.push([longitude, latitude]); pointInput.longitude = ''; pointInput.latitude = ''; error.value = '';
}
function enterPoint() { if (!pointInput.longitude.trim() || !pointInput.latitude.trim()) { error.value = '请填写经纬度。'; return; } addPoint(); }
function undo() { if (!drawing.value || !editable.value) return; const parts = drawing.value.geometry.parts; if (!parts.at(-1)!.length && parts.length > 1) parts.pop(); else parts.at(-1)!.pop(); }
function nextPart() { if (!drawing.value || !editable.value) return; const parts = drawing.value.geometry.parts; if (parts.at(-1)!.length < 2 || parts.length >= 100) { error.value = '每段至少两个点，最多 100 段。'; return; } parts.push([]); }
async function readFile(file: File | undefined) {
  if (!file || !editable.value) return; if (fileInput.value) fileInput.value.value = '';
  if (file.size > geometryLimits.gpxBytes) { error.value = 'GPX 文件最多 1MiB，请先分割或简化。'; return; }
  if (!drawing.value) start('gpx'); if (!drawing.value || drawing.value.kind !== 'gpx') return;
  try { drawing.value.xml = new TextDecoder('utf-8', { fatal: true }).decode(await file.arrayBuffer()); drawing.value.filename = file.name.slice(0, 200); preview.value = null; await previewGpx(); } catch (e) { error.value = errorText(e); }
}
async function previewGpx() { if (!drawing.value?.xml) return; busy.value = true; error.value = ''; try { preview.value = await api('/geometries/gpx-preview', 'POST', { xml: drawing.value.xml }); drawing.value.geometry = clone(preview.value!.geometry); } catch (e) { preview.value = null; error.value = errorText(e); } finally { busy.value = false; persistDrawing(); } }
async function saveGeometry() {
  if (!drawing.value || !segment.value || !editable.value || dirty.value) return; if (drawing.value.kind === 'gpx' && (!preview.value || !drawing.value.rightsConfirmed)) { error.value = '请先预览 GPX，并确认有权保存和导出文件。'; return; }
  busy.value = true; error.value = ''; const d = drawing.value;
  const common = { baseVersion: d.baseVersion, clientMutationId: d.key, expectedGeometryRef: d.expectedGeometryRef, sourceNote: d.sourceNote };
  const body: GeometrySaveInput = d.kind === 'gpx' ? { ...common, kind: 'gpx', xml: d.xml, filename: d.filename, rightsConfirmed: d.rightsConfirmed } : { ...common, kind: 'manual', geometry: d.geometry };
  try {
    const result = await api<{ route: RouteSnapshot; asset: GeometryAsset }>(`/routes/${route.value!.id}/segments/${d.segmentId}/geometry`, 'PUT', body);
    drawing.value = null; persistDrawing(); action.value = 'none'; preview.value = null; draft.initialize(result.route); assetGeneration++; assetLoading.value = false; asset.value = result.asset; await loadAssets(); message.value = '路径已保存；请查看来源和端点诊断，再主动确认核对。';
  } catch (e) { error.value = errorText(e); if (e instanceof ApiError && e.status === 409) drawingConflict.value = true; persistDrawing(); } finally { busy.value = false; }
}
function discardDrawing() { if (!drawing.value || busy.value || !window.confirm('放弃此页面尚未保存的路径草稿？')) return; drawing.value = null; preview.value = null; drawingConflict.value = false; action.value = 'none'; persistDrawing(); }
function assetCommand(type: 'review' | 'lock' | 'clear') {
  if (!segment.value || !editable.value || drawing.value) return; const s = segment.value;
  if (type === 'clear' && !window.confirm('移除当前路径绑定？历史资产保留。保存行程后生效。')) return;
  const op = type === 'lock' ? { type: 'set_segment_lock' as const, segmentId: s.id, locked: !s.geometryLocked } : type === 'clear' ? { type: 'clear_segment_geometry' as const, segmentId: s.id, geometryRef: s.geometryRef! } : { type: 'review_segment' as const, segmentId: s.id, geometryRef: s.geometryRef! };
  draft.stage([op]);
}
async function adoptCandidate(result: { route: RouteSnapshot; asset: GeometryAsset }) { draft.initialize(result.route); assetGeneration++; assetLoading.value = false; asset.value = result.asset; routingPreview.value = null; action.value = 'none'; await loadAssets(); }
async function saveRoute() { await draft.save(); if (!dirty.value && !conflict.value) { await loadAssets(); await loadAsset(); } }
async function showExport() { if (!route.value || dirty.value || drawing.value) return; busy.value = true; error.value = ''; partialOK.value = false; try { report.value = await api(`/routes/${route.value.id}/gpx-export-preview`); modal.value = 'export'; } catch (e) { error.value = errorText(e); } finally { busy.value = false; } }
function download(text: string, filename: string, mime = 'application/json') { const url = URL.createObjectURL(new Blob([text], { type: mime })); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
async function exportGpx() { if (!route.value || !report.value) return; busy.value = true; error.value = ''; try { const result = await api<{ xml: string; filename: string }>(`/routes/${route.value.id}/gpx-export`, 'POST', { baseVersion: report.value.routeVersion, allowPartial: partialOK.value }); download(result.xml, result.filename, 'application/gpx+xml'); modal.value = null; } catch (e) { error.value = errorText(e); } finally { busy.value = false; } }
function downloadDraft() { if (drawing.value) download(JSON.stringify(drawing.value, null, 2), '迹屿-路径草稿.json'); if (dirty.value) draft.exportDraft(); }
async function reload() {
  if (!route.value) return; busy.value = true; error.value = '';
  try { await draft.reload(); await loadAssets(); await loadAsset(); drawingConflict.value = !!drawing.value; modal.value = null; message.value = drawing.value ? '已加载最新路线，路径草稿仍保留；核对当前起终点和绑定后再选择继续。' : '已加载服务器版本'; }
  catch (e) { error.value = errorText(e); } finally { busy.value = false; }
}
function rebaseDrawing() { if (!drawing.value || !segment.value || dirty.value || !window.confirm('已核对当前起终点、交通方式与已有路径，使用本页草稿继续？这不会自动保存。')) return; drawing.value.baseVersion = base.value!.version; drawing.value.expectedGeometryRef = segment.value.geometryRef; drawing.value.key = mutationId(); drawingConflict.value = false; persistDrawing(); }
function leave(answer: boolean, discard = false) { if (discard) { draft.discard(); drawing.value = null; persistDrawing(); } else { draft.write(); persistDrawing(); } modal.value = null; resolveLeave?.(answer); resolveLeave = undefined; }
onBeforeRouteLeave(() => { if (busy.value || routingBusy.value || saving.value) return false; if (!dirty.value && !drawing.value) return true; return new Promise<boolean>(resolve => { resolveLeave = resolve; modal.value = 'leave'; }); });
const beforeUnload = (event: BeforeUnloadEvent) => { if (dirty.value || drawing.value || busy.value || routingBusy.value || saving.value) { event.preventDefault(); event.returnValue = ''; } };
onMounted(() => window.addEventListener('beforeunload', beforeUnload)); onBeforeUnmount(() => { draft.write(); persistDrawing(); assetGeneration++; resolveLeave?.(false); window.removeEventListener('beforeunload', beforeUnload); });
</script>
<template><section class="flow-view"><header class="flow-topbar"><button class="icon-button" aria-label="返回行程" @click="router.push('/journeys/' + page.params.id + (actual ? '/actual' : ''))"><AtlasIcon name="back"/></button><h2>{{ actual ? '实际路径' : '路线地图' }}</h2><span class="icon-button"/></header><div class="flow-scroll map-page"><p v-if="loading" class="form-intro">正在打开路线…</p><p v-else-if="loadError" class="flow-form-errors" role="alert">{{ loadError }}<button class="text-button" @click="load">重新加载</button></p><template v-else-if="route"><h1 class="editor-title">{{ journey?.title }}</h1><p class="small muted">{{ actual ? '回程补记' : '行前规划' }} · 地点与路径分别保存，补绘和参考文件均非自动确认的 GPS 实录。</p><div v-if="dirty || drawing" class="flow-draft-banner"><div class="draft-info"><strong>本页有未保存修改</strong><span>{{ storageOK && draft.storageOK.value ? '草稿保留于此浏览器页面' : '本机存储不可用，请下载草稿' }}</span></div><button @click="downloadDraft">下载草稿</button></div><p v-if="error" class="flow-form-errors" role="alert">{{ error }}</p><p v-if="message || savedMessage" class="flow-save-state" role="status">{{ message || savedMessage }}</p><div v-if="conflict || drawingConflict" class="map-conflict"><p>服务器或路径绑定已变化，草稿保留。请先下载并核对。</p><button class="secondary-button" :disabled="busy || saving" @click="modal = 'reload'">加载最新路线并核对</button><button v-if="drawingConflict && !conflict" class="text-button" :disabled="busy || dirty" @click="rebaseDrawing">已核对当前路线，使用本页路径继续</button></div>
<div class="map-button-row map-provider"><button class="secondary-button" :aria-pressed="mapMode === 'amap'" @click="mapMode = 'amap'">高德地图</button><button class="secondary-button" :aria-pressed="mapMode === 'outdoor'" @click="mapMode = 'outdoor'">社区户外地图</button></div><p v-if="routingPreview" class="map-notice" role="status">正在显示候选预览，尚未代表当前绑定路径。候选 {{ routingPreview.id.slice(0, 8) }}</p><RouteMapCanvas v-if="mapMode === 'amap'" :locations="stops" :geometry="geometry" :action="editable ? action : 'none'" @pick="mapPick"/><OutdoorMapCanvas v-else :locations="stops" :geometry="geometry" :action="editable ? action : 'none'" @pick="mapPick"/>
<section class="map-panel"><h3>地点位置</h3><p v-if="!stops.length" class="muted">先回行程添加地点，再安排路径。</p><fieldset v-else :disabled="!editable || !!drawing" class="map-fields"><div class="flow-field"><label for="map-stop">选择地点</label><select id="map-stop" v-model="stopId"><option v-for="p in stops" :key="p.id" :value="p.id">{{ p.label }} · {{ p.location ? p.location.crs : '待定位' }}</option></select></div><p v-if="stop?.location" class="small muted">原始位置：{{ stop.location.longitude }}, {{ stop.location.latitude }} · {{ stop.location.crs }} · {{ stop.location.source === 'outdoor_pick' ? '户外地图选点' : stop.location.source === 'amap_pick' ? '高德地图选点' : stop.location.source === 'gpx_endpoint' ? '文件端点' : '手工坐标' }}</p><button class="secondary-button" :aria-pressed="action === 'point'" @click="action = action === 'point' ? 'none' : 'point'">{{ action === 'point' ? '取消地图选点' : '在地图上为此地点选点' }}</button><details><summary>手工填写坐标</summary><div class="coordinate-grid"><div class="flow-field"><label for="location-lon">地点经度</label><input id="location-lon" v-model="locationInput.longitude" inputmode="decimal" placeholder="经度"></div><div class="flow-field"><label for="location-lat">地点纬度</label><input id="location-lat" v-model="locationInput.latitude" inputmode="decimal" placeholder="纬度"></div></div><div class="flow-field"><label for="location-crs">原始坐标系</label><select id="location-crs" v-model="locationInput.crs"><option value="WGS84">WGS84 · GPS／GPX</option><option value="GCJ02">GCJ-02 · 高德</option><option value="BD09">BD-09 · 百度</option></select></div><button class="text-button" @click="enterLocation">将坐标加入修改</button><button v-if="stop?.location" class="text-button danger" @click="updateLocation(null)">清除地点位置</button></details></fieldset></section>
<section class="map-panel"><h3>地点之间的路径</h3><p v-if="!route.segments.length" class="muted">至少两个地点才有连接，系统不会自动连成徒步轨迹。</p><template v-else><div class="flow-field"><label for="map-segment">选择连接</label><select id="map-segment" v-model="segmentId" :disabled="busy || routingBusy || saving || !!drawing"><option v-for="s in route.segments" :key="s.id" :value="s.id">{{ names(s.fromStopId) }} → {{ names(s.toStopId) }} · {{ modeLabels[s.mode] }}</option></select></div><p class="small muted">当前 {{ assets.length }} 条路径资产绑定；跨日或未安排交通的连接保留为缺口。</p><template v-if="segment"><div v-if="!drawing" class="map-mode-row"><select v-model="mode" aria-label="路段交通方式" :disabled="!editable"><option v-for="m in travelModes" :key="m" :value="m">{{ modeLabels[m] }}</option></select><button class="text-button" :disabled="!editable" @click="setMode">更新这段交通</button></div><p v-if="segment.kind === 'gap'" class="map-notice">这是一处接驳缺口。明确交通方式并保存后，再补绘或导入路径。</p><p v-if="segment.geometryStatus === 'stale'" class="flow-form-errors">路径已过期：起终点或交通方式发生变化。原路径仅供回查，不能按当前路线导出。</p><p v-if="assetLoading" class="muted">正在读取路径…</p><article v-if="asset" class="geometry-summary"><strong>{{ geometrySourceLabels[asset.sourceKind] }} · {{ asset.geometry.crs }}</strong><p>{{ asset.sourceNote }}</p><p class="small muted">{{ asset.pointCount }} 点 · {{ asset.geometry.parts.length }} 个独立分段 · 二维线长约 {{ (asset.lengthM / 1000).toFixed(2) }}km，不等于实际运动里程</p><ul v-if="asset.diagnostics.length"><li v-for="d in asset.diagnostics" :key="d">{{ d }}</li></ul><p>{{ segment.reviewStatus === 'confirmed' ? '你已核对此版本' : '尚需你查看端点和来源后主动核对' }} · {{ segment.geometryLocked ? '已保护' : '未保护' }}</p><p v-if="asset.exportPolicy !== 'allowed'" class="small muted">此路径的 GPX 导出条件未满足；不会将 GCJ-02 直接写成 WGS84。</p><div class="map-button-row"><button class="secondary-button" :disabled="!editable || !!drawing || segment.geometryStatus !== 'ready' || segment.reviewStatus === 'confirmed'" @click="assetCommand('review')">已核对这段路径</button><button class="text-button" :disabled="!editable || !!drawing" @click="assetCommand('lock')">{{ segment.geometryLocked ? '解除路径保护' : '保护这段路径' }}</button><button class="text-button danger" :disabled="!editable || !!drawing || segment.geometryLocked" @click="assetCommand('clear')">移除路径绑定</button><a v-if="asset.filename" class="text-button" :href="'/api/v1/geometries/' + asset.id + '/original'" download>下载原始 GPX</a></div></article>
<RoutingPanel v-if="base" :route="base" :segment-id="segmentId" :blocked="dirty || !!drawing || !editable" @preview="routingPreview = $event" @busy="routingBusy = $event" @adopted="adoptCandidate"/><div v-if="!drawing" class="map-create"><p v-if="dirty" class="small muted">先保存行程修改，再开始补绘或导入。</p><p v-if="segment.geometryLocked" class="small muted">先解除路径保护并保存，才能替换。</p><div class="flow-field"><label for="drawing-crs">补绘坐标来源</label><select id="drawing-crs" v-model="manualCrs" :disabled="!editable"><option value="GCJ02">在高德上逐点补绘 · GCJ-02</option><option value="WGS84">户外地图或自有坐标补绘 · WGS84</option></select></div><div class="map-button-row"><button class="primary" :disabled="!editable || dirty || segment.kind === 'gap' || segment.geometryLocked" @click="start('manual')">手工补绘这段</button><button class="secondary-button" :disabled="!editable || dirty || segment.kind === 'gap' || segment.geometryLocked" @click="start('gpx'); fileInput?.click()">导入 GPX 到这段</button></div></div>
<section v-if="drawing" class="geometry-editor"><h4>{{ drawing.kind === 'manual' ? '路径补绘草稿' : 'GPX 导入预览' }}</h4><p class="small muted">目标：{{ names(segment.fromStopId) }} → {{ names(segment.toStopId) }}。保存会替换当前绑定，旧资产保留。</p><fieldset class="map-fields" :disabled="!editable"><template v-if="drawing.kind === 'manual'"><p>{{ drawing.geometry.crs }} · {{ pointCount }} 点 · {{ drawing.geometry.parts.length }} 段</p><p v-if="drawing.geometry.crs === 'GCJ02'" class="small muted">可在已加载的高德地图逐点点击；此来源暂不支持 GPX 导出。</p><p v-else class="small muted">可在已加载的户外地图逐点点击，或填写有权使用的 WGS84 坐标；高德坐标不能直接填成 WGS84。</p><div class="coordinate-grid"><div class="flow-field"><label for="path-lon">路径点经度</label><input id="path-lon" v-model="pointInput.longitude" inputmode="decimal"></div><div class="flow-field"><label for="path-lat">路径点纬度</label><input id="path-lat" v-model="pointInput.latitude" inputmode="decimal"></div></div><div class="map-button-row"><button class="secondary-button" @click="enterPoint">添加路径点</button><button class="text-button" @click="undo">撤回最后一点</button><button class="text-button" @click="nextPart">从缺口后另起一段</button></div></template><template v-else><button class="secondary-button" @click="fileInput?.click()">选择 GPX 文件</button><p class="small muted">UTF-8 GPX 1.0／1.1，最多 1MiB／10000 点。支持轨迹和路线，原文件私密保留。</p><p>{{ drawing.filename || '尚未选择文件' }}</p><button v-if="drawing.xml && !preview" class="text-button" @click="previewGpx">重新解析预览</button><div v-if="preview"><p>{{ preview.pointCount }} 点 · {{ preview.geometry.parts.length }} 段 · 二维线长约 {{ (preview.lengthM / 1000).toFixed(2) }}km</p><ul><li v-for="warning in preview.warnings" :key="warning">{{ warning }}</li></ul></div><label class="map-check"><input v-model="drawing.rightsConfirmed" type="checkbox">我有权在此保存和导出该文件；这不赋予其他来源额外授权。</label></template><div class="flow-field"><label for="geometry-source">路径来源与使用说明</label><textarea id="geometry-source" v-model="drawing.sourceNote" maxlength="2000" rows="3" placeholder="例如：本人设备导出；或参考资料名称、来源链接及许可"></textarea></div></fieldset><div class="map-button-row"><button class="primary" :disabled="!editable || dirty" @click="saveGeometry">{{ busy ? '正在处理…' : '保存路径到服务器' }}</button><button class="text-button" :disabled="busy || saving" @click="discardDrawing">放弃路径草稿</button></div></section></template></template><input ref="fileInput" class="visually-hidden" type="file" accept=".gpx,application/gpx+xml,application/xml,text/xml" aria-label="GPX 文件" :disabled="!editable" @change="readFile(($event.target as HTMLInputElement).files?.[0])"></section>
<button class="secondary-button full" :disabled="dirty || !!drawing || busy || routingBusy || saving" @click="showExport">预览 GPX 导出范围</button></template></div><footer v-if="route" class="flow-bottom"><span class="save-info">{{ dirty ? '行程位置／核对状态有待保存' : `服务器版本 ${base?.version}` }}</span><button class="primary" :disabled="!dirty || !editable || !!drawing" @click="saveRoute">{{ saving ? '正在保存…' : '保存行程修改' }}</button></footer><ModalSheet v-if="modal" :title="modal === 'leave' ? '路线修改尚未保存' : modal === 'reload' ? '核对服务器路线' : 'GPX 导出范围'" :busy="busy" @close="modal === 'leave' ? leave(false) : modal = null"><template v-if="modal === 'leave'"><p>本页位置或路径草稿尚未保存，可以保留在当前浏览器页面。</p><button class="text-button" @click="downloadDraft">下载当前草稿</button></template><template v-else-if="modal === 'reload'"><p>请先下载草稿。加载最新路线会放弃待提交的地点／核对修改，路径点和 GPX 草稿仍保留，不会自动覆盖服务器。</p><button class="text-button" @click="downloadDraft">下载当前草稿</button></template><template v-else-if="report"><p>当前 {{ report.total }} 段连接，含 {{ report.included }} 条路径、{{ report.missing }} 条缺失路径、{{ report.gaps }} 处接驳缺口。</p><ul v-if="report.blockers.length"><li v-for="blocker in report.blockers" :key="blocker">{{ blocker }}</li></ul><p v-else>按原始 WGS84 坐标导出；各路径／断段保持独立，采样信息按原文件保留，不自动标为 GPS 实录。</p><label v-if="report.partial" class="map-check"><input v-model="partialOK" type="checkbox">我确认只导出已有路径，未覆盖段不会被补直线。</label></template><template #footer><div v-if="modal === 'leave'" class="modal-actions"><button class="primary" :disabled="!storageOK || !draft.storageOK.value" @click="leave(true)">保留草稿并离开</button><button class="secondary-button" @click="leave(false)">继续编辑</button><button class="text-button" @click="leave(true, true)">放弃本页修改并离开</button></div><button v-else-if="modal === 'reload'" class="primary" :disabled="busy" @click="reload">加载最新路线，保留路径草稿</button><button v-else class="primary" :disabled="busy || !!report?.blockers.length || !!report?.partial && !partialOK" @click="exportGpx">下载 GPX 文件</button></template></ModalSheet></section></template>
